<div class="admin-title"><div><span class="eyebrow">PRIVATE BY DESIGN</span><h1><?= e($title) ?></h1><p><?= t('One record per signed-in member, private file and day. Authorization is checked before recording; repeat access to the same file does not consume another daily slot.') ?></p></div><a class="btn secondary" href="<?= e(au('settings',['group'=>'security'])) ?>"><?= t('Download limits') ?></a></div><section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th><?= t('Member') ?></th><th><?= t('File') ?></th><th><?= t('First authorized request') ?></th></tr></thead><tbody><?php foreach($a->db->all('SELECT d.*,u.display_name,m.name FROM cy_downloads d JOIN cy_users u ON u.id=d.user_id JOIN cy_media m ON m.id=d.media_id ORDER BY d.id DESC LIMIT 200') as $row): ?><tr><td>#<?= (int)$row['user_id'] ?> <?= e($row['display_name']) ?></td><td>#<?= (int)$row['media_id'] ?> <?= e($row['name']) ?></td><td><?= dt((int)$row['created_at']) ?></td></tr><?php endforeach ?></tbody></table></div><p class="hint"><?= t('A record is an authorized request, not proof that a client completed the transfer. Anonymous access is not counted; use login or paid access for quota enforcement.') ?></p></section>
